async function fetchCompressAndConvertToBase64(imageUrl, maxDimension, quality) {
    maxDimension = maxDimension || 1200;
    quality = quality || 0.7;

    const token = localStorage.getItem("token");
    const response = await fetch(imageUrl, {
        headers: { Authorization: `Bearer ${token}` }
    });

    if (!response.ok) {
        return null;
    }

    const blob = await response.blob();
    const contentType = blob.type || 'image/png';
    const bitmap = await createImageBitmap(blob);

    let width = bitmap.width;
    let height = bitmap.height;

    if (width > maxDimension || height > maxDimension) {
        if (width > height) {
            height = Math.round(height * (maxDimension / width));
            width = maxDimension;
        } else {
            width = Math.round(width * (maxDimension / height));
            height = maxDimension;
        }
    }

    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(bitmap, 0, 0, width, height);
    bitmap.close();

    const outputType = contentType === 'image/png' ? 'image/png' : 'image/jpeg';
    const dataUri = canvas.toDataURL(outputType, quality);

    return dataUri;
}

window.fetchCompressAndConvertToBase64 = fetchCompressAndConvertToBase64;

async function embedAllDocLibUrlsAsBase64InHtml(htmlContent, docLibBaseUrl, maxDimension, quality) {
    if (!htmlContent || !htmlContent.trim()) return htmlContent;

    maxDimension = maxDimension || 1200;
    quality = quality || 0.7;

    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlContent, 'text/html');

    // Collect all elements with DocLib URLs: img[src] and object[data]
    const selectors = [
        { elements: doc.querySelectorAll('img[src]'), attr: 'src' },
        { elements: doc.querySelectorAll('object[data]'), attr: 'data' }
    ];

    // Build a map of unique DocLib URLs to convert (avoid duplicate downloads)
    const urlCache = {};

    for (const { elements, attr } of selectors) {
        for (const el of elements) {
            const url = el.getAttribute(attr);
            if (url && url.includes('/api/Document/DownloadStream') && !url.startsWith('data:')) {
                if (!(url in urlCache)) {
                    urlCache[url] = null; // placeholder
                }
            }
        }
    }

    // Download and convert all unique URLs
    const token = localStorage.getItem('token');
    await Promise.all(
        Object.keys(urlCache).map(async (url) => {
            try {
                const response = await fetch(url, {
                    headers: { Authorization: `Bearer ${token}` }
                });

                if (!response.ok) return;

                const blob = await response.blob();
                const contentType = blob.type || 'image/png';
                const bitmap = await createImageBitmap(blob);

                let width = bitmap.width;
                let height = bitmap.height;

                if (width > maxDimension || height > maxDimension) {
                    if (width > height) {
                        height = Math.round(height * (maxDimension / width));
                        width = maxDimension;
                    } else {
                        width = Math.round(width * (maxDimension / height));
                        height = maxDimension;
                    }
                }

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                canvas.getContext('2d').drawImage(bitmap, 0, 0, width, height);
                bitmap.close();

                const outputType = contentType === 'image/png' ? 'image/png' : 'image/jpeg';
                urlCache[url] = canvas.toDataURL(outputType, quality);
            } catch (e) {
                // Leave original URL if download fails
            }
        })
    );

    // Replace attributes with Base64 data URIs
    for (const { elements, attr } of selectors) {
        for (const el of elements) {
            const url = el.getAttribute(attr);
            if (url && urlCache[url]) {
                el.setAttribute(attr, urlCache[url]);
            }
        }
    }

    // Serialize back — use body's innerHTML to avoid wrapping html/head/body tags
    return doc.body.innerHTML;
}

window.embedAllDocLibUrlsAsBase64InHtml = embedAllDocLibUrlsAsBase64InHtml;

window.getMarkedAnswersFromEditor = function (componentGuid) {
    const editorTextArea = document.getElementById(`suneditor_editor-${componentGuid}`);
    if (!editorTextArea) return [];
    const editableArea = editorTextArea.querySelector('.sun-editor-editable');
    if (!editableArea) return [];
    return Array.from(editableArea.querySelectorAll('span.marked-answer'))
        .map(s => s.textContent.trim())
        .filter(t => t.length > 0);
};